import React, { useState, useEffect } from "react";
import "./ProductsPage.scss";

import ProductsList from "../../components/ProductsList";
import ProductModal from "../../components/ProductModal";
import AuthModal from "../../components/AuthModal";
import RegisterModal from "../../components/RegisterModal";
import { api } from "../../api";

export default function ProductsPage() {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);

    const [modalOpen, setModalOpen] = useState(false);
    const [modalMode, setModalMode] = useState("create");
    const [editingProduct, setEditingProduct] = useState(null);

    const [authModalOpen, setAuthModalOpen] = useState(false);

    const [registerModalOpen, setRegisterModalOpen] = useState(false);


    useEffect(() => {
        loadProducts();
    }, []);

    const loadProducts = async () => {
        try {
            setLoading(true);
            const data = await api.getProducts();
            setProducts(data);
        } catch (err) {
            console.error(err);
            alert("Ошибка загрузки товаров");
        } finally {
            setLoading(false);
        }
    };

    const openCreate = () => {
        setModalMode("create");
        setEditingProduct(null);
        setModalOpen(true);
    };

    const openAuth = () => {
        setAuthModalOpen(true);
    }

    const closeAuth = () => {
        setAuthModalOpen(false);
    }


    const handleSubmitAuth = async (payload) => {
        try {
            const data = await api.login(payload);
            localStorage.setItem('accessToken', data.accessToken);
            localStorage.setItem('refreshToken', data.refreshToken);
            alert(`Успешная авторизация пользователя ${payload.email}`);
            closeAuth();
        } catch (err) {
            console.error(err);
            alert("Ошибка авторизации");
        }
    };


    const openRegister = () => {
        setRegisterModalOpen(true);
    }

    const closeRegister = () => {
        setRegisterModalOpen(false);
    }

    const handleSubmitRegister = async (payload) => {
        try {
            alert(`Успешная регистрация пользователя ${payload.email}`);
            closeRegister()
        } catch (err) {
            console.error(err);
            alert("Ошибка регистрации")
        }
    }


    const openEdit = (product) => {
        setModalMode("edit");
        setEditingProduct(product);
        setModalOpen(true);
    };

    const closeModal = () => {
        setModalOpen(false);
        setEditingProduct(null);
    };

    const handleDelete = async (id) => {
        const ok = window.confirm("Удалить товар?");
        if (!ok) return;

        try {
            await api.deleteProduct(id);
            setProducts((prev) => prev.filter((p) => p.id !== id));
        } catch (err) {
            console.error(err);
            alert("Ошибка удаления товара");
        }
    };

    const handleSubmitModal = async (payload) => {
        try {
            if (modalMode === "create") {
                const newProduct = await api.createProduct(payload);
                setProducts((prev) => [...prev, newProduct]);
            } else {
                const updatedProduct = await api.updateProduct(payload.id, payload);
                setProducts((prev) =>
                    prev.map((p) => (p.id === payload.id ? updatedProduct : p))
                );
            }
            closeModal();
        } catch (err) {
            console.error(err);
            alert("Ошибка сохранения товара");
        }
    };

    return (
        <div className="page">
            <header className="header">
                <div className="container">
                    <div className="header__inner">
                        <div className="brand">Магазин</div>
                    </div>
                    <div>
                        <button className="btn btn--primary" onClick={openAuth}>
                            Авторизоваться
                        </button>
                    </div>
                </div>


            </header>

            <main className="main">
                <div className="container">
                    <div className="toolbar">
                        <h1 className="title">Товары</h1>
                        <button className="btn btn--primary" onClick={openCreate}>
                            + Добавить товар
                        </button>
                    </div>

                    {loading ? (
                        <div className="empty">Загрузка...</div>
                    ) : (
                        <ProductsList
                            products={products}
                            onEdit={openEdit}
                            onDelete={handleDelete}
                        />
                    )}
                </div>
            </main>

            <footer className="footer">
                <div className="footer__inner">
                    {new Date().getFullYear()} Интернет-магазин
                </div>
            </footer>

            <ProductModal
                open={modalOpen}
                mode={modalMode}
                initialProduct={editingProduct}
                onClose={closeModal}
                onSubmit={handleSubmitModal}
            />

            <AuthModal
                open={authModalOpen}
                onClose={closeAuth}
                onSubmit={handleSubmitAuth}
            />

            <RegisterModal
                open={registerModalOpen}
                onClose={closeRegister}
                onSubmit={handleSubmitRegister}
            />
        </div>
    );
}
